const CLIENT_LOG_KEY='picarx-client-events';
function recordClientEvent(message:string,details?:Record<string,unknown>){try{const previous=JSON.parse(localStorage.getItem(CLIENT_LOG_KEY)||'[]') as RuntimeEvent[];const events=[{timestamp:new Date().toISOString(),level:'ERROR',category:'frontend',message,details},...previous].slice(0,200);localStorage.setItem(CLIENT_LOG_KEY,JSON.stringify(events));}catch{/* Logging must never interfere with vehicle safety. */}}
function readDriveButtons():DriveButton[]{try{const value=JSON.parse(localStorage.getItem('picarx-drive-buttons')||'null');if(!Array.isArray(value))return DEFAULT_DRIVE_BUTTONS;const allowed=new Set<DriveButton['action']>(['forward','backward','left','right','brake','stop','emergencyStop','increasePwm','decreasePwm']);const cleaned=value.filter((item):item is DriveButton=>item&&typeof item.id==='string'&&typeof item.label==='string'&&allowed.has(item.action));if(!cleaned.length)return DEFAULT_DRIVE_BUTTONS;for(const action of ['increasePwm','decreasePwm','left','right'] as DriveAction[]){if(!cleaned.some(item=>item.action===action)){const fallback=DEFAULT_DRIVE_BUTTONS.find(item=>item.action===action);if(fallback)cleaned.push({...fallback});}}return cleaned.slice(0,9).map(item=>({id:item.id,action:item.action,label:item.label,position:item.position==='right'?'right':'left'}));}catch{return DEFAULT_DRIVE_BUTTONS;}}
function sensorSeries(records:SensorSample[],select:(row:SensorSample)=>number|null):string{const values=records.map(select),valid=values.filter((value):value is number=>typeof value==='number'&&Number.isFinite(value));if(valid.length<2)return'';const low=Math.min(...valid),high=Math.max(...valid),span=high-low||1;return values.map((value,index)=>value===null?null:`${(index/Math.max(1,values.length-1))*600},${120-((value-low)/span)*100}`).filter(Boolean).join(' ');}
function impactDynamicValue(sample:ImpactSample):number|null{if(typeof sample.dynamic_g==='number'&&Number.isFinite(sample.dynamic_g))return sample.dynamic_g;if([sample.delta_x_g,sample.delta_y_g,sample.delta_z_g].every(value=>typeof value==='number'&&Number.isFinite(value))){return Math.sqrt((sample.delta_x_g as number)**2+(sample.delta_y_g as number)**2+(sample.delta_z_g as number)**2);}return null;}
// 그래프 세로 범위: 최소 0–2 g, 더 큰 충격은 잘리지 않도록 자동 확장합니다.
function impactScaleMax(samples:ImpactSample[]):number{let peak=0;for(const sample of samples){const d=impactDynamicValue(sample);if(d!==null&&d>peak)peak=d;if(typeof sample.vertical_g==='number'&&sample.vertical_g>peak)peak=sample.vertical_g;}return Math.max(2,Math.ceil(peak*2)/2);}
function impactGraphPoints(samples:ImpactSample[],scale=impactScaleMax(samples)):string{return samples.map((sample,index,rows)=>{const value=impactDynamicValue(sample);return value===null?null:`${index/Math.max(1,rows.length-1)*600},${130-Math.min(scale,value)/scale*120}`;}).filter((point):point is string=>point!==null).join(' ');}
function impactVerticalPoints(samples:ImpactSample[],scale=impactScaleMax(samples)):string{return samples.map((sample,index,rows)=>typeof sample.vertical_g!=='number'?null:`${index/Math.max(1,rows.length-1)*600},${130-Math.max(0,Math.min(scale,sample.vertical_g))/scale*120}`).filter((point):point is string=>point!==null).join(' ');}
function hasImpactGraphData(samples:ImpactSample[]):boolean{return samples.filter(sample=>impactDynamicValue(sample)!==null).length>1;}
