 const poll=useRef<number>(),hold=useRef<number>(),sensorPoll=useRef<number>(),impactPollBusy=useRef(false),lastSteeringAt=useRef(0),manualDisconnect=useRef(false),active=useRef<Direction|null>(null),desired=useRef<{direction:Direction;steering:number;speed?:number}>({direction:'forward',steering:0}),rampedSpeed=useRef(0),speedRef=useRef({forward,reverse,steer,targetPwm});speedRef.current={forward,reverse,steer,targetPwm};
