 async function steerTo(angle:number){const safe=Math.round(Math.max(-steer,Math.min(steer,angle)));desired.current.steering=safe;if(active.current)return;const now=Date.now();if(Math.abs(safe)>0&&now-lastSteeringAt.current<140)return;lastSteeringAt.current=now;const direction=safe<0?'left':safe>0?'right':'center';try{setVehicleStatus(await request('/api/settings/steering-test',{method:'POST',body:JSON.stringify({direction,angle:Math.abs(safe)})}) as Status);}catch(e){setError(e instanceof Error?e.message:t('calibrationError'));}}
 function updateStick(e:PointerEvent<HTMLDivElement>){const {nx,ny}=stickVector(e,setJoystick);const angle=Math.round(Math.sign(nx)*Math.pow(Math.abs(nx),1.2)*speedRef.current.steer);const raw=Math.max(0,ny-.08)/.92;const speed=Math.round(Math.pow(raw,1.5)*speedRef.current.forward);joySpeed.current=speed;setJoyPwm(speed);if(active.current)desired.current.speed=speed;void steerTo(angle);}
