 function renderDriveButton(button:DriveButton){return <button key={button.id} type="button" className={`drive-btn act-${button.action}${button.action==='forward'?' forward':''}`} onContextMenu={e=>e.preventDefault()} onPointerDown={e=>{e.currentTarget.setPointerCapture(e.pointerId);driveButtonDown(button);}} onPointerUp={()=>driveButtonUp(button)} onPointerCancel={()=>driveButtonUp(button)} onLostPointerCapture={()=>driveButtonUp(button,true)}><span className="drive-glyph">{button.action==='forward'?<ArrowUp/>:button.action==='backward'?<ArrowDown/>:button.action==='left'?<ArrowLeft/>:button.action==='right'?<ArrowRight/>:button.action==='increasePwm'?<span className="literal-plus">+</span>:button.action==='decreasePwm'?<Minus/>:<CircleStop/>}</span><b>{button.label}</b></button>;}
